tool_input.command:
G=$(powershell -c "[guid]::NewGuid()") && python - "$G" <<'EOF' 2>/dev/null || python3 - "$G" <<'EOF2'
EOF
cat >> Collection.cs <<EOF

namespace BenchPlugin
{
    [GrasshopperCollection("Bench", "Geometry")]
    public interface IGeometryPack : IBettaCollection
    {
        [GrasshopperMethod("Divide Curve Stats", "Divide a curve into equal-length segments", Guid = "$G")]
        (System.Collections.Generic.List<Rhino.Geometry.Point3d> Points, double Length) DivideCurveStats(
            [GrasshopperParameter("Curve")] Rhino.Geometry.Curve curve,
            [GrasshopperParameter("Count", DefaultValue = 10)] int count);
    }

    public class GeometryPack : IGeometryPack
    {
        public (System.Collections.Generic.List<Rhino.Geometry.Point3d> Points, double Length) DivideCurveStats(
            Rhino.Geometry.Curve curve, int count)
        {
            if (curve == null) throw new System.ArgumentNullException(nameof(curve));
            if (count < 1) throw new System.ArgumentException("Count must be at least 1.", nameof(count));
            var points = curve.DivideByCount(count, true, out var _) is { } ts
                ? new System.Collections.Generic.List<Rhino.Geometry.Point3d>(ts.Select(curve.PointAt))
                : new System.Collections.Generic.List<Rhino.Geometry.Point3d>();
            return (points, curve.GetLength());
        }
    }
}
EOF
dotnet build 2>&1 | tail -8
